import{_ as a,o as e,c as r,al as i}from"./chunks/framework.7vp1BMOE.js";const c=JSON.parse('{"title":"Gear Up AirBrainH743","description":"","frontmatter":{},"headers":[],"relativePath":"ko/flight_controller/gearup_airbrainh743.md","filePath":"ko/flight_controller/gearup_airbrainh743.md"}'),o={name:"ko/flight_controller/gearup_airbrainh743.md"};function d(s,t,l,n,h,p){return e(),r("div",null,[...t[0]||(t[0]=[i('<h1 id="gear-up-airbrainh743" tabindex="-1">Gear Up AirBrainH743 <a class="header-anchor" href="#gear-up-airbrainh743" aria-label="Permalink to &quot;Gear Up AirBrainH743&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>PX4 does not manufacture this (or any) autopilot. Contact the <a href="https://takeyourgear.com/" target="_blank" rel="noreferrer">manufacturer</a> for hardware support.</p></div><div class="info custom-block"><p class="custom-block-title">INFO</p><p>This flight controller is <a href="./../flight_controller/autopilot_manufacturer_supported">manufacturer supported</a>.</p></div><p>Purchase from <a href="https://takeyourgear.com/pages/products/airbrain" target="_blank" rel="noreferrer">takeyourgear.com</a>.</p><p>For more information and pinout, check the <a href="https://github.com/GearUp-Company/AirBrainH743" target="_blank" rel="noreferrer">GitHub documentation</a>.</p><h2 id="주요-특징" tabindex="-1">주요 특징 <a class="header-anchor" href="#주요-특징" aria-label="Permalink to &quot;주요 특징&quot;">​</a></h2><ul><li>MCU: STM32H743 32-bit processor running at 480 MHz</li><li>IMU: ICM42688P</li><li>Barometer: DPS310</li><li>Magnetometer: LIS2MDL (internal)</li><li>128MB NAND Flash for logging (W25N)</li><li>7x UARTs</li><li>I2C, SPI</li><li>9x PWM Outputs (8 Motor outputs, 1 LED strip)</li><li>Battery input voltage: 3S-10S</li><li>Battery voltage/current monitoring</li><li>5V@2A and 10V@2.5A BEC outputs</li><li>USB Type-C (IP68)</li><li>EMC and ESD protection</li></ul><h2 id="커넥터-및-핀" tabindex="-1">커넥터 및 핀 <a class="header-anchor" href="#커넥터-및-핀" aria-label="Permalink to &quot;커넥터 및 핀&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>The pin order is different from the Pixhawk standard (compatible to the Betaflight standard).</p></div><h3 id="uart" tabindex="-1">UART <a class="header-anchor" href="#uart" aria-label="Permalink to &quot;UART&quot;">​</a></h3><p>Current UART configuration:</p><table tabindex="0"><thead><tr><th>UART</th><th>장치</th><th>기능</th></tr></thead><tbody><tr><td>USART1</td><td>/dev/ttyS0</td><td>Console/Debug</td></tr><tr><td>USART2</td><td>/dev/ttyS1</td><td>RC Input</td></tr><tr><td>USART3</td><td>/dev/ttyS2</td><td>TEL4 (DJI/MSP)</td></tr><tr><td>UART4</td><td>/dev/ttyS3</td><td>TEL1</td></tr><tr><td>UART5</td><td>/dev/ttyS4</td><td>TEL2</td></tr><tr><td>UART7</td><td>/dev/ttyS5</td><td>TEL3 (ESC Telemetry)</td></tr><tr><td>UART8</td><td>/dev/ttyS6</td><td>GPS1</td></tr></tbody></table><h3 id="motor-servo-outputs" tabindex="-1">Motor/Servo Outputs <a class="header-anchor" href="#motor-servo-outputs" aria-label="Permalink to &quot;Motor/Servo Outputs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>커넥터</th><th>핀</th><th>기능</th></tr></thead><tbody><tr><td>ESC</td><td>M1</td><td>Motor 1</td></tr><tr><td>ESC</td><td>M2</td><td>Motor 2</td></tr><tr><td>ESC</td><td>M3</td><td>Motor 3</td></tr><tr><td>ESC</td><td>M4</td><td>Motor 4</td></tr><tr><td>PWM</td><td>M5</td><td>Motor 5</td></tr><tr><td>PWM</td><td>M6</td><td>Motor 6</td></tr><tr><td>PWM</td><td>M7</td><td>Motor 7</td></tr><tr><td>PWM</td><td>M8</td><td>Motor 8</td></tr><tr><td>AUX</td><td>M9</td><td>LED/PWM/etc.</td></tr></tbody></table><p><a id="bootloader"></a></p><h2 id="부트로더-업데이트" tabindex="-1">부트로더 업데이트 <a class="header-anchor" href="#부트로더-업데이트" aria-label="Permalink to &quot;부트로더 업데이트&quot;">​</a></h2><p>Before PX4 firmware can be installed, the <em>PX4 bootloader</em> must be flashed. Download the <a href="https://github.com/PX4/PX4-Autopilot/blob/main/boards/gearup/airbrainh743/extras/gearup_airbrainh743_bootloader.bin" target="_blank" rel="noreferrer">gearup_airbrainh743_bootloader.bin</a> bootloader binary and read <a href="./../advanced_config/bootloader_update_from_betaflight">this page</a> for flashing instructions.</p><h2 id="펌웨어-빌드" tabindex="-1">펌웨어 빌드 <a class="header-anchor" href="#펌웨어-빌드" aria-label="Permalink to &quot;펌웨어 빌드&quot;">​</a></h2><p>To <a href="./../dev_setup/building_px4">build PX4</a> for this target:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gearup_airbrainh743_default</span></span></code></pre></div><h2 id="펌웨어-설치" tabindex="-1">펌웨어 설치 <a class="header-anchor" href="#펌웨어-설치" aria-label="Permalink to &quot;펌웨어 설치&quot;">​</a></h2><p>Firmware can be installed in any of the normal ways:</p><ul><li><p>Build and upload the source:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gearup_airbrainh743_default</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> upload</span></span></code></pre></div></li><li><p><a href="./../config/firmware">Load the firmware</a> using <em>QGroundControl</em>. 미리 빌드된 펌웨어나 사용자 지정 펌웨어를 사용할 수 있습니다.</p></li></ul><h3 id="flash-storage-troubleshooting" tabindex="-1">Flash Storage Troubleshooting <a class="header-anchor" href="#flash-storage-troubleshooting" aria-label="Permalink to &quot;Flash Storage Troubleshooting&quot;">​</a></h3><p>The AirBrainH743 uses a 128MB NAND flash (W25N) with a littlefs filesystem for <a href="./../dev_log/logging">logging</a>. If the flash filesystem becomes corrupted, you can reformat it using the <a href="./../debug/system_console">System Console</a>:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mklittlefs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /dev/mtd0</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /fs/flash</span></span></code></pre></div><p>This will erase all data on the flash and create a fresh littlefs filesystem. The filesystem is immediately available after the command completes.</p><h3 id="시스템-콘솔" tabindex="-1">시스템 콘솔 <a class="header-anchor" href="#시스템-콘솔" aria-label="Permalink to &quot;시스템 콘솔&quot;">​</a></h3><p>UART1 (ttyS0) is configured for use as the <a href="./../debug/system_console">System Console</a>.</p>',29)])])}const b=a(o,[["render",d]]);export{c as __pageData,b as default};
